import { createRequire } from "node:module";

async function classify(name, operation) {
  try {
    await operation();
    return `${name}:REACHED`;
  } catch {
    return `${name}:DENIED`;
  }
}

export async function deniedMatrix() {
  const text = "./denied-text.txt";
  const json = "./denied-json.json";
  const bytes = "./denied-bytes.bin";
  return await Promise.all([
    classify(
      "literal-text",
      () => import("./denied-text.txt", { with: { type: "text" } }),
    ),
    classify(
      "literal-json",
      () => import("./denied-json.json", { with: { type: "json" } }),
    ),
    classify(
      "literal-bytes",
      () => import("./denied-bytes.bin", { with: { type: "bytes" } }),
    ),
    classify("computed-text", () => import(text, { with: { type: "text" } })),
    classify("computed-json", () => import(json, { with: { type: "json" } })),
    classify(
      "computed-bytes",
      () => import(bytes, { with: { type: "bytes" } }),
    ),
    classify(
      "create-require",
      () => createRequire(import.meta.url)("./denied-json.json"),
    ),
  ]);
}
